-- Fleet Manager Pro: PostgreSQL / Supabase V1 schema.
-- Run in Supabase SQL editor after creating a project.
create extension if not exists pgcrypto;
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,organization_id uuid references public.organizations(id),full_name text not null default '',role text not null default 'viewer' check(role in('admin','manager','viewer')),created_at timestamptz not null default now());
create table public.vehicles(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,plate text not null,name text not null,brand text,type text not null check(type in('Camion','Voiture','Engin','Utilitaire')),status text not null default 'Disponible' check(status in('En service','Maintenance','Disponible')),odometer numeric(12,2) not null default 0 check(odometer>=0),model_year integer,service_due date,created_at timestamptz not null default now(),unique(organization_id,plate));
create table public.drivers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,full_name text not null,phone text,license_number text,license_expiry date,active boolean not null default true);
create table public.assignments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,vehicle_id uuid not null references public.vehicles(id),driver_id uuid not null references public.drivers(id),start_at timestamptz not null,end_at timestamptz,check(end_at is null or end_at>=start_at));
create table public.maintenance(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,vehicle_id uuid not null references public.vehicles(id),title text not null,scheduled_on date not null,completed_on date,cost numeric(12,2) not null default 0 check(cost>=0),status text not null default 'Planifiée' check(status in('Planifiée','Terminée')),notes text,created_at timestamptz not null default now());
create table public.fuel_logs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,vehicle_id uuid not null references public.vehicles(id),filled_on date not null,liters numeric(10,2) not null check(liters>0),amount numeric(12,2) not null check(amount>=0),odometer numeric(12,2),created_at timestamptz not null default now());
create table public.vehicle_documents(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,vehicle_id uuid not null references public.vehicles(id),kind text not null,expires_on date,storage_path text,created_at timestamptz not null default now());
create table public.missions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,vehicle_id uuid references public.vehicles(id),driver_id uuid references public.drivers(id),title text not null,origin text,destination text,starts_at timestamptz,ends_at timestamptz,status text not null default 'Planifiée',created_at timestamptz not null default now());
create index on public.vehicles(organization_id,status);create index on public.maintenance(organization_id,scheduled_on);create index on public.fuel_logs(organization_id,filled_on);create index on public.vehicle_documents(organization_id,expires_on);
create or replace function public.current_org() returns uuid language sql stable security definer set search_path=public as $$select organization_id from public.profiles where id=(select auth.uid())$$;
create or replace function public.can_edit() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=(select auth.uid()) and role in('admin','manager'))$$;
-- Restrict every tenant table to its own organization. Membership onboarding should be handled server-side.
alter table public.organizations enable row level security;alter table public.profiles enable row level security;
create policy org_read on public.organizations for select to authenticated using(id=(select public.current_org()));
create policy profile_read on public.profiles for select to authenticated using(organization_id=(select public.current_org()));
-- Profiles/roles cannot be changed by regular users; provision via trusted backend.
do $$declare t text;begin foreach t in array array['vehicles','drivers','assignments','maintenance','fuel_logs','vehicle_documents','missions'] loop
execute format('alter table public.%I enable row level security',t);
execute format('create policy %I on public.%I for select to authenticated using(organization_id=(select public.current_org()))',t||'_read',t);
execute format('create policy %I on public.%I for insert to authenticated with check(organization_id=(select public.current_org()) and (select public.can_edit()))',t||'_insert',t);
execute format('create policy %I on public.%I for update to authenticated using(organization_id=(select public.current_org()) and (select public.can_edit())) with check(organization_id=(select public.current_org()) and (select public.can_edit()))',t||'_update',t);
execute format('create policy %I on public.%I for delete to authenticated using(organization_id=(select public.current_org()) and (select public.can_edit()))',t||'_delete',t);
end loop;end$$;
-- Before production, enforce same-organization foreign keys with triggers or composite keys.
